
const WORDS=[{"id": 0, "w": "白噪音", "p": "bái zàoyīn", "t": "名词", "m": "tiếng ồn trắng", "coll": "播放白噪音、白噪音录音", "s": "这段白噪音录音模拟了雨声，有人喜欢在阅读时播放，也有人觉得不习惯。"}, {"id": 1, "w": "嘈杂", "p": "cáozá", "t": "形容词", "m": "ồn ào, huyên náo", "coll": "环境嘈杂、嘈杂的声音", "s": "周围环境过于嘈杂，他只好换到安静的房间，继续完成录音。"}, {"id": 2, "w": "莫名其妙", "p": "mòmíngqímiào", "t": "成语", "m": "không thể giải thích được, kỳ lạ, khó hiểu", "coll": "感到莫名其妙、莫名其妙地生气", "s": "对方突然改变了主意，却没有说明原因，让她感到莫名其妙。"}, {"id": 3, "w": "淘汰", "p": "táotài", "t": "动词", "m": "đào thải, loại bỏ", "coll": "淘汰落后设备、面临淘汰", "s": "那些效率低下的设备逐渐被淘汰，取而代之的是更加节能的新产品。"}, {"id": 4, "w": "不妨", "p": "bùfáng", "t": "副词", "m": "có thể làm, đừng ngại, tốt nhất là", "coll": "不妨试试、不妨考虑", "s": "如果暂时找不到思路，你不妨出去走走，回来后再重新考虑。"}, {"id": 5, "w": "描绘", "p": "miáohuì", "t": "动词", "m": "miêu tả, mô tả", "coll": "描绘景色、生动描绘", "s": "作者用细腻的语言，描绘了海边清晨的景色。"}, {"id": 6, "w": "波浪", "p": "bōlàng", "t": "名词", "m": "sóng", "coll": "层层波浪、波浪起伏", "s": "风渐渐大了，海面上翻起层层波浪，渔船也开始返回港口。"}, {"id": 7, "w": "岩石", "p": "yánshí", "t": "名词", "m": "đá, khối đá", "coll": "坚硬的岩石、岩石表面", "s": "经过长期的冲刷，这些岩石的表面变得光滑，留下了岁月的痕迹。"}, {"id": 8, "w": "抚摸", "p": "fǔmō", "t": "动词", "m": "vuốt ve, xoa, vỗ về", "coll": "轻轻抚摸、抚摸头发", "s": "母亲轻轻抚摸孩子的头发，耐心听他讲述学校里发生的事。"}, {"id": 9, "w": "务必", "p": "wùbì", "t": "副词", "m": "nhất thiết phải", "coll": "务必注意、务必完成", "s": "提交申请之前，请务必检查所有材料，确认信息填写无误。"}, {"id": 10, "w": "警惕", "p": "jǐngtì", "t": "动词", "m": "cảnh giác", "coll": "提高警惕、保持警惕", "s": "面对来历不明的信息，我们应当保持警惕，先核实再作决定。"}, {"id": 11, "w": "解除", "p": "jiěchú", "t": "动词", "m": "hủy bỏ, xua tan", "coll": "解除限制、解除误会", "s": "经过坦诚的交流，双方终于解除了误会，重新建立了信任。"}, {"id": 12, "w": "不得已", "p": "bùdéyǐ", "t": "形容词", "m": "bất đắc dĩ, bắt buộc phải, không thể không như vậy", "coll": "不得已而为之、实在不得已", "s": "实在不得已，他才临时取消了行程，留在家里处理急事。"}, {"id": 13, "w": "暴露", "p": "bàolù", "t": "动词", "m": "bộc lộ, để lộ", "coll": "暴露问题、暴露身份", "s": "这次故障暴露了管理中的问题，提醒大家及时检查相关流程。"}, {"id": 14, "w": "惹祸", "p": "rě huò", "t": "动词", "m": "gây rắc rối, gây tai họa, chuốc lấy tai họa", "coll": "惹祸上身、到处惹祸", "s": "他终于意识到，随意传播未经证实的消息可能会惹祸上身。"}, {"id": 15, "w": "雌雄", "p": "cíxióng", "t": "名词", "m": "đực cái", "coll": "雌雄差异、辨别雌雄", "s": "研究人员通过观察羽毛的颜色，尝试辨别这些鸟的雌雄。"}, {"id": 16, "w": "祖先", "p": "zǔxiān", "t": "名词", "m": "tổ tiên, ông bà", "coll": "纪念祖先、祖先的智慧", "s": "这些传统技艺凝聚着祖先的智慧，值得我们认真了解和传承。"}, {"id": 17, "w": "遗留", "p": "yíliú", "t": "动词", "m": "để lại, truyền lại", "coll": "遗留问题、遗留物品", "s": "工作人员正在清点旅客遗留的物品，设法联系失主。"}, {"id": 18, "w": "嘛", "p": "ma", "t": "助词", "m": "(biểu thị lý lẽ rõ ràng) đi, mà...", "coll": "慢慢来嘛、别着急嘛", "s": "别着急嘛，材料还没有准备齐全，我们再检查一遍。"}, {"id": 19, "w": "延续", "p": "yánxù", "t": "动词", "m": "tiếp tục, kéo dài", "coll": "延续传统、延续至今", "s": "这个节日习俗已经延续至今，仍然是当地生活的重要组成部分。"}, {"id": 20, "w": "后代", "p": "hòudài", "t": "名词", "m": "đời sau, thế hệ sau", "coll": "子孙后代、培养后代", "s": "保护自然环境，既关系到我们自己，也关系到子孙后代的生活。"}, {"id": 21, "w": "呼唤", "p": "hūhuàn", "t": "动词", "m": "kêu gào, kêu to", "coll": "呼唤名字、大声呼唤", "s": "听见有人呼唤自己的名字，她停下脚步，转身朝声音传来的方向望去。"}, {"id": 22, "w": "竖", "p": "shù", "t": "动词", "m": "dựng thẳng", "coll": "竖起耳朵、竖起牌子", "s": "工作人员在入口处竖起一块牌子，提醒游客注意安全。"}, {"id": 23, "w": "原始", "p": "yuánshǐ", "t": "形容词", "m": "nguyên thủy", "coll": "原始森林、原始资料", "s": "研究者重新整理原始资料，希望找到之前被忽略的线索。"}, {"id": 24, "w": "进化", "p": "jìnhuà", "t": "动词", "m": "tiến hóa", "coll": "生物进化、进化过程", "s": "这本书通过具体例子，介绍了生物进化的基本概念。"}, {"id": 25, "w": "靠拢", "p": "kàolǒng", "t": "动词", "m": "dựa sát, áp sát, đến gần", "coll": "向中间靠拢、逐渐靠拢", "s": "为了拍好合影，摄影师请大家再向中间靠拢一些。"}, {"id": 26, "w": "神经", "p": "shénjīng", "t": "名词", "m": "dây thần kinh; thần kinh", "coll": "神经系统、神经细胞", "s": "老师借助模型，向学生介绍了神经系统的基本结构。"}, {"id": 27, "w": "生物", "p": "shēngwù", "t": "名词", "m": "sinh vật", "coll": "海洋生物、生物多样性", "s": "保护湿地，有助于维护当地的生物多样性，保存不同物种的栖息地。"}, {"id": 28, "w": "配偶", "p": "pèi'ǒu", "t": "名词", "m": "phối ngẫu, vợ, chồng", "coll": "选择配偶、寻找配偶", "s": "研究人员长期观察这种鸟类，记录它们寻找配偶时的行为。"}, {"id": 29, "w": "世代", "p": "shìdài", "t": "名词", "m": "nhiều đời, mấy đời", "coll": "世代相传、世代居住", "s": "这门手艺在村里世代相传，如今又吸引了许多年轻人学习。"}, {"id": 30, "w": "暗示", "p": "ànshì", "t": "动词", "m": "ngụ ý, ám thị, có hàm ý", "coll": "暗示答案、眼神暗示", "s": "她没有直接回答，只是用眼神暗示我，先看看桌上的说明。"}, {"id": 31, "w": "提示", "p": "tíshì", "t": "动词", "m": "nhắc nhở, gợi ý", "coll": "提示信息、温馨提示", "s": "屏幕上出现了提示信息，提醒使用者先保存当前文件。"}, {"id": 32, "w": "鉴于", "p": "jiànyú", "t": "连词／介词", "m": "do, bởi vì; xét thấy", "coll": "鉴于情况、鉴于上述原因", "s": "鉴于天气发生变化，组织者决定调整路线，并及时通知所有参加者。"}, {"id": 33, "w": "功效", "p": "gōngxiào", "t": "名词", "m": "tác dụng, hiệu lực, hiệu quả", "coll": "实际功效、发挥功效", "s": "讨论这种产品的功效时，应当查看可靠的研究资料，避免只凭广告作判断。"}, {"id": 34, "w": "理所当然", "p": "lǐsuǒdāngrán", "t": "成语", "m": "đương nhiên, dĩ nhiên", "coll": "认为理所当然、理所当然的事", "s": "我们不应该把别人的帮助看作理所当然，而忘记表达感谢。"}, {"id": 35, "w": "疾病", "p": "jíbìng", "t": "名词", "m": "bệnh tật", "coll": "预防疾病、疾病研究", "s": "这项研究关注生活环境与某些疾病之间可能存在的联系。"}, {"id": 36, "w": "患者", "p": "huànzhě", "t": "名词", "m": "người bệnh, bệnh nhân", "coll": "接待患者、患者家属", "s": "工作人员耐心地向患者家属说明了办理手续的流程。"}, {"id": 37, "w": "辅助", "p": "fǔzhù", "t": "动词／形容词", "m": "phụ, bổ trợ", "coll": "辅助工具、辅助教学", "s": "这套图像资料可以作为辅助工具，帮助学生理解较为抽象的概念。"}, {"id": 38, "w": "症状", "p": "zhèngzhuàng", "t": "名词", "m": "triệu chứng", "coll": "描述症状、出现症状", "s": "填写问卷时，请如实描述出现的症状，不要遗漏重要信息。"}, {"id": 39, "w": "愈", "p": "yù", "t": "动词", "m": "khỏi bệnh, hết bệnh", "coll": "病愈、愈合", "s": "病愈之后，她回到学校，继续完成中断的学业。"}, {"id": 40, "w": "障碍", "p": "zhàng'ài", "t": "名词", "m": "sự trở ngại, sự cản trở, chướng ngại vật", "coll": "沟通障碍、克服障碍", "s": "使用清晰的语言和具体的例子，有助于减少跨文化交流中的障碍。"}, {"id": 41, "w": "噪音", "p": "zàoyīn", "t": "名词", "m": "tiếng ồn", "coll": "减少噪音、交通噪音", "s": "为了减少噪音，学校把活动场地安排在远离教室的地方。"}, {"id": 42, "w": "给予", "p": "jǐyǔ", "t": "动词", "m": "cho, dành cho", "coll": "给予支持、给予帮助", "s": "在他最困难的时候，朋友们给予了支持，帮助他重新振作起来。"}, {"id": 43, "w": "嘿", "p": "hēi", "t": "叹词", "m": "(biểu thị sự nhắc nhở, gọi) này, nè", "coll": "嘿，你好、嘿，等等", "s": "嘿，你落下的书还在桌上，别忘了带走。"}];
